        answer: 'Wersja z kolorowym dotykowym LCD 4,3" (warianty ZD6A1xx) kosztuje około 277 zł netto więcej od wersji bez LCD. Wyświetlacz oferuje intuicyjne menu konfiguracyjne, animowane instrukcje ładowania mediów i diagnostykę błędów. Warto go wybrać, jeśli drukarki obsługuje wielu operatorów lub gdy potrzebujesz szybkiej konfiguracji bez podłączania komputera. W środowisku z jednym przeszkolonym operatorem wersja bez LCD jest wystarczająca.',
