        answer: 'ZT111 to drukarka klasy przemysłowej z metalową ramą, obsługująca rolki mediów do 203 mm (vs 127 mm w ZD421), taśmy 450 m (vs 300 m) i drukująca z prędkością do 254 mm/s (vs 152 mm/s). ZT111 jest zaprojektowana do większych wolumenów druku i pracy w wymagających środowiskach — magazynach, halach produkcyjnych i centrach dystrybucyjnych. ZD421 to drukarka biurkowa do biur i stanowisk pakowania.',
